# ==========================================
# Data Hyperparameters
# ==========================================
IMAGE_SIZE = 224
NUM_SLICES_PER_MODALITY = 32
NUM_MODALITIES = 4
# Total input channels = 32 slices * 4 modalities = 128
INPUT_CHANNELS = NUM_SLICES_PER_MODALITY * NUM_MODALITIES

# ==========================================
# Model Hyperparameters
# ==========================================
# The adapter compresses 128 channels -> 64 channels
ADAPTER_OUT_CHANNELS = 64
BACKBONE_NAME = "efficientnet_b0"
DROP_PATH_RATE = 0.2

# ==========================================
# Training Hyperparameters
# ==========================================
SEED = 42
BATCH_SIZE = 16  # A100 40GB can handle this density easily
LEARNING_RATE = 1e-4
NUM_EPOCHS = 15
NUM_WORKERS = 4
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")


# ==========================================
# Utility Functions
# ==========================================
def set_seed(seed=SEED):
    """
    Sets the random seed for reproducibility across Python, NumPy, and PyTorch.
    """
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed(seed)
    torch.cuda.manual_seed_all(seed)
    # Ensure deterministic behavior for cuDNN
    torch.backends.cudnn.deterministic = True
    torch.backends.cudnn.benchmark = False
